// Original executable workbenches for communication and journal workflows.
import {makeWorkbenchTutorial} from './tutorial-workbench.mjs';
const text=(name,label,value='',required=true)=>({name,label,type:'text',value,required});
const check=(name,label,value=false)=>({name,label,type:'checkbox',value});
const number=(name,label,value)=>({name,label,type:'number',value,required:true});
const rid=text('id','Document UUID');
const recipe=(id,fields,code,enTitle,ptTitle,enInstruction,ptInstruction,enExpected,ptExpected,enVerify,ptVerify)=>({id,fields,code,en:{title:enTitle,instruction:enInstruction,expected:enExpected,verify:enVerify},pt:{title:ptTitle,instruction:ptInstruction,expected:ptExpected,verify:ptVerify}});
const readBackEN='Open the native directory or document and compare its server state. Compare GM and player views; only authorized content may appear.';
const readBackPT='Abra o diretório ou documento nativo e compare o estado do servidor. Compare mestre e jogador; apenas conteúdo autorizado pode aparecer.';
const chatRecipes=[
  recipe('history',[text('sceneId','Scene UUID, optional','',false)],String.raw`async ({api,signal},v)=>api.chat.history(v.sceneId.trim()?{sceneId:v.sceneId.trim()}:{},{signal})`,
    'Read visible chat history','Ler o histórico visível','Leave Scene UUID empty to use the broadcast scene, or enter an authorized scene UUID. The returned array is the visible recent history, not every message ever sent.','Deixe Scene UUID vazio para usar a cena transmitida ou informe uma cena autorizada. O array retornado é o histórico recente visível, não todas as mensagens já enviadas.','Message IDs, authors, text and visibility for this account.','IDs de mensagens, autores, texto e visibilidade desta conta.','Compare sender, whisper recipient and an unrelated player. Hidden messages must be absent.','Compare remetente, destinatário de sussurro e outro jogador. Mensagens ocultas não podem aparecer.'),
  recipe('public-message',[text('text','Public message','The harbor gates are open.'),text('sceneId','Scene UUID, optional','',false)],String.raw`async ({api,signal},v)=>{const text=v.text.trim();if(text.startsWith('/'))throw new Error('Use a dedicated command recipe.');return api.chat.send({text,...(v.sceneId.trim()?{sceneId:v.sceneId.trim()}:{})},{signal,requestId:crypto.randomUUID()});}`,
    'Send one public message','Enviar uma mensagem pública','Enter original text. This recipe rejects a leading slash so the public action cannot accidentally become a command. Optional scene selection uses sceneId.','Informe texto original. A receita rejeita barra inicial para que a ação pública não se torne comando sem intenção. A cena opcional usa sceneId.','One visible chat message and its server ID.','Uma mensagem visível e seu ID no servidor.','Check native chat as two table members. Run again only if you intend a second message.','Confira o chat nativo com dois membros. Execute novamente apenas se quiser uma segunda mensagem.'),
  recipe('whisper',[text('recipient','Exact member display name'),text('text','Private message','Meet me at the lighthouse.')],String.raw`async ({api,signal},v)=>api.chat.send({text:'/w '+v.recipient.trim()+' '+v.text.trim()},{signal,requestId:crypto.randomUUID()})`,
    'Send a recipient-bound whisper','Enviar um sussurro ao destinatário','Enter the exact display name of a member in this campaign, including spaces. Native /w parsing resolves members, not a client-supplied audience list. Identical display names can resolve multiple matching members.','Informe o nome de exibição exato de um membro, incluindo espaços. O comando nativo /w resolve os membros, não uma lista de audiência inventada no cliente. Nomes de exibição iguais podem corresponder a vários membros.','The server returns a whisper visible to sender and matching recipients.','O servidor retorna sussurro visível ao remetente e destinatários correspondentes.','Read history as recipient and nonrecipient; only the former receives the content. Use unique test names.','Leia o histórico como destinatário e não destinatário; só o primeiro recebe o conteúdo. Use nomes únicos no teste.'),
  recipe('gm-message',[text('text','Message to GMs','A hidden passage was found.')],String.raw`async ({api,signal},v)=>api.chat.send({text:'/gm '+v.text.trim()},{signal,requestId:crypto.randomUUID()})`,
    'Send a message to the GMs','Enviar uma mensagem aos mestres','The /gm native command addresses campaign GMs plus the sender. It is a chat command, not a visibility field on chat.send.','O comando nativo /gm envia aos mestres da campanha e ao remetente. É um comando de chat, não um campo visibility em chat.send.','A recipient-filtered message in GM and sender chat.','Uma mensagem filtrada no chat de mestres e remetente.',readBackEN,readBackPT),
  recipe('emote',[text('text','Emote text','lights the harbor beacon.')],String.raw`async ({api,signal},v)=>api.chat.send({text:'/me '+v.text.trim()},{signal,requestId:crypto.randomUUID()})`,
    'Publish an emote','Publicar uma ação de personagem','Enter an action. The native /me command marks the message as an emote and retains normal public delivery.','Informe uma ação. O comando nativo /me marca a mensagem como ação e mantém a entrega pública.','A chat message with metadata.emote true.','Uma mensagem com metadata.emote verdadeiro.',readBackEN,readBackPT),
  recipe('dice',[text('expression','Dice expression','2d6+1'),text('label','Label, up to 48 characters','Harbor check'),number('repeat','Repeat, integer 1 to 12',1),check('secret','GM-only result')],String.raw`async ({api,signal},v)=>{if(!Number.isInteger(v.repeat)||v.repeat<1||v.repeat>12)throw new Error('Repeat must be 1 to 12.');return api.dice.roll(v.expression,{label:v.label,repeat:v.repeat,visibility:v.secret?'gm':'public'},{signal,requestId:crypto.randomUUID()});}`,
    'Roll and publish public or GM-only dice','Rolar e publicar dados públicos ou exclusivos do mestre','Enter an expression supported by the native parser, label and repeat count. GM-only result chooses visibility gm. This action persists and publishes a roll; it is not a local calculator.','Informe expressão aceita pelo parser, rótulo e repetições. GM-only result escolhe visibility gm. A ação persiste e publica uma rolagem; não é calculadora local.','One durable submission containing the requested roll(s), with the selected audience.','Uma submissão persistida com as rolagens e a audiência escolhida.','Compare public and GM-only rolls in two accounts. Reject repeat 0 or 13. A retry of the same logical submission must reuse its original UUID rather than roll again.','Compare rolagens públicas e de mestre em duas contas. Rejeite repetição 0 ou 13. Uma tentativa da mesma submissão deve reutilizar o UUID original em vez de rolar novamente.'),
  recipe('remove-message',[text('messageId','Numeric message ID')],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('GM required.');if(!/^\d+$/.test(v.messageId))throw new Error('Use the numeric chat ID from history.');return api.chat.remove(v.messageId,{signal});}`,
    'Moderate one message','Moderar uma mensagem','As GM, copy the numeric ID from history. This removes that message content and attachments while preserving retry identity.','Como mestre, copie o ID numérico do histórico. A ação remove conteúdo e anexos dessa mensagem, preservando a identidade para tentativas.','A removed count; subsequent history omits that message.','Quantidade removida; históricos seguintes omitem a mensagem.','Moderate only a synthetic message created for this tutorial. A player must be rejected by the server.','Modere apenas mensagem sintética criada para o tutorial. O servidor deve rejeitar um jogador.'),
  recipe('clear-chat',[text('confirmation','Type CLEAR CHAT')],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('GM required.');if(v.confirmation!=='CLEAR CHAT')throw new Error('Type CLEAR CHAT to clear the whole campaign chat.');return api.chat.clear({signal});}`,
    'Clear the disposable campaign chat','Limpar o chat da campanha descartável','Use only a disposable campaign. Type CLEAR CHAT. This GM moderation operation is campaign-wide, including scenes, rather than just the history currently displayed.','Use somente campanha descartável. Digite CLEAR CHAT. A moderação do mestre abrange a campanha inteira e suas cenas, não apenas o histórico exibido.','All undeleted messages in this campaign are removed.','Todas as mensagens ainda não removidas da campanha são apagadas.','Read history in another scene and confirm it is also cleared. Submission receipts remain.','Leia o histórico de outra cena e confirme a limpeza. Os recibos de submissão permanecem.'),
  recipe('lobby',[],String.raw`async ({api,signal})=>api.table.lobby({signal})`,
    'Inspect the ready check and selectable actors','Inspecionar a prontidão e os atores selecionáveis','The installation must have its native ready check enabled. Read members, summary and the actors this account may select.','A instalação deve ter a verificação nativa de prontidão habilitada. Leia membros, resumo e atores que esta conta pode selecionar.','members, actors and summary.ready/total.','members, actors e summary.ready/total.','Compare a read-only actor with an actor owned by this player; only controllable actors are selectable.','Compare um ator somente leitura com um pertencente ao jogador; apenas os controláveis são selecionáveis.'),
  recipe('set-ready',[check('ready','I am ready',true),text('actorId','Selected owned actor UUID, optional','',false),text('assets','Asset state: unknown/loading/ready/error','ready')],String.raw`async ({api,signal},v)=>{if(!['unknown','loading','ready','error'].includes(v.assets))throw new Error('Choose a native assets_state.');if(v.actorId.trim()){const lobby=await api.table.lobby({signal});if(!lobby.actors.some(actor=>actor.id===v.actorId.trim()))throw new Error('Actor is not selectable.');}return api.table.updateLobby({is_ready:v.ready,assets_state:v.assets,selected_actor_id:v.actorId.trim()||null},{signal});}`,
    'Update this member’s ready state','Atualizar a prontidão deste membro','Set the checkbox, a selectable actor UUID from the lobby result, and assets_state. Leave actor UUID blank to clear the selection. The API chooses the current member; no user ID can impersonate someone else.','Escolha a prontidão, UUID selecionável do resultado do lobby e assets_state. Deixe o ator vazio para limpar a seleção. A API usa o membro atual; não recebe ID de usuário para imitar outra pessoa.','The returned lobby has this member’s new selection and readiness.','O lobby retornado tem a seleção e prontidão atualizadas deste membro.','Use two accounts: only the current member’s row changes. Unknown actor or assets state must fail.','Use duas contas: apenas a linha do membro atual muda. Ator ou estado de recursos desconhecido deve falhar.'),
  recipe('search',[text('query','At least two search characters','Harbor'),text('kind','Kind, optional','',false)],String.raw`async ({api,signal},v)=>{const kind=v.kind.trim();if(!['','actor','item','journal','quest','quest_board','scene','compendium'].includes(kind))throw new Error('Unknown search kind.');return api.table.search(v.query,{...(kind?{kind}:{}),signal});}`,
    'Search all seven document kinds','Buscar os sete kinds de documento','Use at least two characters. Blank kind searches all; accepted filters are actor, item, journal, quest, quest_board, scene and compendium. A result is a search projection with title, kind, snippet and actions, not a full document.','Use pelo menos dois caracteres. Kind vazio busca tudo; filtros: actor, item, journal, quest, quest_board, scene e compendium. O resultado contém title, kind, snippet e actions, não o documento completo.','An array of up to 20 authorized matches.','Um array com até 20 resultados autorizados.','Search the same private title as GM and player; it must be absent for the player. Test quest separately from journal.','Busque o mesmo título privado como mestre e jogador; ele deve estar ausente para o jogador. Teste quest separado de journal.'),
  recipe('recent',[text('type','Reference type: actor/item/journal/scene/compendium','journal'),text('id','Previously seen document UUID')],String.raw`async ({api,signal},v)=>{if(!['actor','item','journal','scene','compendium'].includes(v.type))throw new Error('Invalid reference type.');return api.table.search('',{recent:[{id:v.id,type:v.type}],signal});}`,
    'Revalidate a recent document','Revalidar um documento recente','Use one previously read result ID. Recent references use type journal for quests and quest boards, while search kind distinguishes those categories. Up to 12 unique references can be supplied in an array.','Use o ID de um resultado já lido. Referências recentes usam type journal para missões e quadros; o kind da busca distingue as categorias. O array aceita até 12 referências únicas.','Only references still readable by the current member are returned.','Retorna apenas referências ainda legíveis para o membro atual.','Remove the player’s read permission, then repeat the same recent reference. It must disappear.','Retire a leitura do jogador e repita a mesma referência recente. Ela deve desaparecer.')
];

const questRecipes=[
  recipe('create-quest',[text('title','Original quest title','Light the Harbor Beacon'),text('summary','Public summary','Bring the lighthouse back into service.'),text('objective','Visible objective','Reach the beacon platform')],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('GM required for the complete seed.');const created=await api.journals.create({title:v.title,journal_type:'quest'},{signal,requestId:crypto.randomUUID()});try{const data={status:'available',public:{summary:v.summary},gm:{},objectives:[{id:'beacon_platform',text:v.objective,completed:false,optional:false,visibleToPlayers:true,sortOrder:10}],rewards:[],tags:['tutorial'],assignees:[]};await api.journals.update({journal_id:created.journal_id,version:created.version,title:v.title,visibility:'private',data},{signal,requestId:crypto.randomUUID()});return api.journals.get(created.journal_id,{}, {signal});}catch(error){throw new Error('Quest '+created.journal_id+' was created; setup failed: '+(error.code||error.message)+'. Inspect it before creating another.');}}`,
    'Create a complete original quest','Criar uma missão original completa','As GM, enter a title, summary and objective. Create allocates an empty quest; the next independent command fills its complete original data. If setup fails, the error includes the created ID so you can repair that document.','Como mestre, informe título, resumo e objetivo. Create cria a missão vazia; outro comando preenche seus dados originais completos. Se a configuração falhar, o erro inclui o ID criado para reparar esse documento.','A private available quest with one visible objective and its UUID/version.','Uma missão privada disponível com um objetivo visível, UUID e versão.',readBackEN,readBackPT),
  recipe('read-quest',[rid],String.raw`async ({api,signal},v)=>{const row=await api.journals.get(v.id,{}, {signal});if(row.type!=='quest')throw new Error('Choose a quest.');return row;}`,
    'Read quest fields and objective IDs','Ler campos da missão e IDs de objetivo','Paste the created journal_id. Copy quest.objectives[].id for the completion action; the GM projection also includes gm notes and secrets that players never receive.','Cole journal_id criado. Copie quest.objectives[].id para concluir um objetivo; a projeção do mestre também contém notas e segredos que jogadores não recebem.','The authorized quest projection, not a raw ORM document.','A projeção autorizada da missão, não um registro direto do banco.',readBackEN,readBackPT),
  recipe('status',[rid,text('status','draft/available/active/completed/failed/archived','active')],String.raw`async ({api,signal},v)=>{const row=await api.journals.get(v.id,{}, {signal});if(row.type!=='quest'||!['draft','available','active','completed','failed','archived'].includes(v.status))throw new Error('Choose a quest and valid status.');await api.journals.setStatus({journal_id:row.id,version:row.version,status:v.status},{signal,requestId:crypto.randomUUID()});return api.journals.get(row.id,{}, {signal});}`,
    'Advance a quest status with its revision','Avançar o estado da missão com revisão','Choose one of the six status values. This reads the current version once, performs one command and reads the result. A conflict is reported rather than retried.','Escolha um dos seis estados. A receita lê a versão uma vez, executa um comando e lê o resultado. Conflitos são informados sem tentativa automática.','The same quest with the requested status and a newer version.','A mesma missão com o estado solicitado e uma versão nova.','Move an available quest to draft and compare its visibility through a player’s board.','Mude uma missão disponível para draft e compare sua visibilidade no quadro do jogador.'),
  recipe('objective',[rid,text('objectiveId','Objective ID','beacon_platform'),check('completed','Completed',true)],String.raw`async ({api,signal},v)=>{const row=await api.journals.get(v.id,{}, {signal});if(row.type!=='quest')throw new Error('Choose a quest.');await api.journals.setObjective({journal_id:row.id,version:row.version,objective_id:v.objectiveId,completed:v.completed},{signal,requestId:crypto.randomUUID()});return api.journals.get(row.id,{}, {signal});}`,
    'Complete or reopen an objective','Concluir ou reabrir um objetivo','Use the ID from the read recipe, not the objective label. Completed is a boolean. The server prevents players from choosing hidden objective IDs.','Use o ID da receita de leitura, não o texto do objetivo. Completed é booleano. O servidor impede que jogadores escolham objetivos ocultos.','Only the chosen objective completion flag changes.','Somente o indicador de conclusão do objetivo escolhido muda.',readBackEN,readBackPT),
  recipe('assign',[rid,text('actorId','Readable actor UUID to assign')],String.raw`async ({api,signal},v)=>{await api.actors.get(v.actorId,{}, {signal});const row=await api.journals.get(v.id,{}, {signal});if(row.type!=='quest')throw new Error('Choose a quest.');await api.journals.assignCharacters({journal_id:row.id,version:row.version,assignees:[...new Set([...(row.quest.assignees||[]),v.actorId])]},{signal,requestId:crypto.randomUUID()});return api.journals.get(row.id,{}, {signal});}`,
    'Assign a readable character without dropping existing assignments','Atribuir um personagem legível sem remover os atuais','Use an actor UUID from the Actors directory or actor API. The recipe keeps visible assignees and adds one unique ID; the server preserves assignments hidden from non-GM editors.','Use um UUID do diretório ou API de atores. A receita mantém os atribuídos visíveis e adiciona um ID único; o servidor preserva atribuições ocultas de editores que não sejam mestres.','quest.assignees includes the chosen character, within the 32-character limit.','quest.assignees inclui o personagem, respeitando o limite de 32 personagens.',readBackEN,readBackPT),
  recipe('create-board',[text('title','Quest board title','Harbor jobs')],String.raw`async ({api,signal},v)=>{const created=await api.journals.create({title:v.title,journal_type:'quest_board'},{signal,requestId:crypto.randomUUID()});return api.journals.get(created.journal_id,{}, {signal});}`,
    'Create an empty quest board','Criar um quadro vazio de missões','Create a quest_board document. Its data is empty; links to quests are separate server-owned board entries. Copy its ID for the next actions.','Crie um documento quest_board. Seus dados são vazios; vínculos a missões são entradas separadas do servidor. Copie o ID para as próximas ações.','An empty board with board_entries and a document UUID.','Um quadro vazio com board_entries e UUID.',readBackEN,readBackPT),
  recipe('board-create-quest',[rid,text('title','New linked quest title','Repair the harbor bell')],String.raw`async ({api,signal},v)=>{const board=await api.journals.get(v.id,{}, {signal});if(board.type!=='quest_board')throw new Error('Choose a quest board.');const result=await api.journals.createBoardQuest({journal_id:board.id,title:v.title},{signal,requestId:crypto.randomUUID()});return {result,board:await api.journals.get(board.id,{}, {signal})};}`,
    'Create and link a quest through the board','Criar e vincular uma missão pelo quadro','Paste the board UUID. The native board-create command creates an available quest in the board folder and links it in one server operation.','Cole o UUID do quadro. O comando nativo board-create cria uma missão disponível na pasta do quadro e vincula em uma operação no servidor.','created_quest_id plus the updated board entries.','created_quest_id e as entradas atualizadas do quadro.',readBackEN,readBackPT),
  recipe('board-add',[rid,text('questId','Existing quest UUID')],String.raw`async ({api,signal},v)=>{await api.journals.addQuest({journal_id:v.id,quest_id:v.questId},{signal,requestId:crypto.randomUUID()});return api.journals.get(v.id,{}, {signal});}`,
    'Link an existing quest','Vincular uma missão existente','Use the board UUID and an existing readable quest UUID. This adds a board relationship; it does not copy quest content.','Use UUID do quadro e de uma missão legível existente. A ação adiciona uma relação; não copia o conteúdo da missão.','The quest appears once in board_entries.','A missão aparece uma vez em board_entries.',readBackEN,readBackPT),
  recipe('board-pin',[rid,text('questId','Linked quest UUID'),check('pinned','Pinned',true)],String.raw`async ({api,signal},v)=>{await api.journals.pinQuest({journal_id:v.id,quest_id:v.questId,pinned:v.pinned},{signal,requestId:crypto.randomUUID()});return api.journals.get(v.id,{}, {signal});}`,
    'Pin or unpin a board card','Fixar ou desafixar um cartão','Use a quest already linked to the chosen board. Pinned is boolean; pinned entries are displayed before ordinary entries.','Use uma missão já vinculada ao quadro. Pinned é booleano; cartões fixados aparecem antes dos demais.','The chosen entry changes pinned, preserving quest data.','A entrada altera pinned e preserva os dados da missão.',readBackEN,readBackPT),
  recipe('board-reorder',[rid],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('Use GM to read the complete board order.');const board=await api.journals.get(v.id,{}, {signal});if(board.type!=='quest_board')throw new Error('Choose a quest board.');const ids=[...board.board_entries].sort((a,b)=>a.sort_order-b.sort_order).map(entry=>entry.quest_id).reverse();await api.journals.reorderQuests({journal_id:board.id,ordered_quest_ids:ids},{signal,requestId:crypto.randomUUID()});return api.journals.get(board.id,{}, {signal});}`,
    'Reverse the complete board order','Inverter a ordem completa do quadro','As GM, read every entry and submit every quest ID exactly once in reversed sort_order. A player’s filtered list is not a complete order. The native command validates the set and rejects concurrent membership changes.','Como mestre, leia todas as entradas e envie cada ID uma vez, invertendo sort_order. A lista filtrada de um jogador não é a ordem completa. O comando valida o conjunto e rejeita mudanças concorrentes nos vínculos.','All sort_order positions change; pinned grouping still has display priority.','As posições sort_order mudam; o grupo fixado mantém prioridade visual.',readBackEN,readBackPT),
  recipe('board-remove',[rid,text('questId','Quest UUID to unlink')],String.raw`async ({api,signal},v)=>{await api.journals.removeQuest({journal_id:v.id,quest_id:v.questId},{signal,requestId:crypto.randomUUID()});return {board:await api.journals.get(v.id,{}, {signal}),quest:await api.journals.get(v.questId,{}, {signal})};}`,
    'Unlink a card while preserving its quest','Desvincular cartão preservando a missão','Choose the board and quest relationship to remove. This is not journal deletion.','Escolha a relação entre quadro e missão a remover. A ação não apaga o documento da missão.','The board no longer links it, while the original quest remains readable.','O quadro deixa de vincular a missão; o documento original continua legível.',readBackEN,readBackPT)
];

const rollRecipes=[
  recipe('create-table',[text('title','Roll table title','Harbor weather'),check('secret','GM-only results'),check('replacement','Allow replacement',false)],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('GM required.');const created=await api.journals.create({title:v.title,journal_type:'roll_table'},{signal,requestId:crypto.randomUUID()});try{await api.journals.update({journal_id:created.journal_id,version:created.version,title:v.title,visibility:'private',data:{withReplacement:v.replacement,resultVisibility:v.secret?'gm':'public',entries:[{id:'clear',name:'Clear sky',weight:3,result:'The beacon is visible across the bay.',active:true,drawn:false,sortOrder:10},{id:'fog',name:'Fog',weight:1,result:'The boats wait for the fog to lift.',active:true,drawn:false,sortOrder:20}]}},{signal,requestId:crypto.randomUUID()});return api.journals.get(created.journal_id,{}, {signal});}catch(error){throw new Error('Roll table '+created.journal_id+' exists; configuration failed: '+(error.code||error.message)+'. Repair this table before creating another.');}}`,
    'Create a weighted original roll table','Criar uma tabela original com pesos','As GM, create journal_type roll_table and configure its two complete entries. Weights 3 and 1 give different probabilities. Without replacement, drawn entries stop being eligible until reset.','Como mestre, crie journal_type roll_table e configure duas entradas completas. Pesos 3 e 1 produzem probabilidades diferentes. Sem reposição, entradas sorteadas deixam de participar até reset.','A table with totalWeight 4, independent entry IDs and the chosen result audience.','Uma tabela com totalWeight 4, IDs próprios de entradas e audiência escolhida.',readBackEN,readBackPT),
  recipe('read-table',[rid],String.raw`async ({api,signal},v)=>{const row=await api.journals.get(v.id,{}, {signal});if(row.type!=='roll_table')throw new Error('Choose a roll_table journal.');return row;}`,
    'Read weights, results and draw flags','Ler pesos, resultados e marcadores de sorteio','Use the table UUID. The projected roll_table contains entries and totalWeight; GM-only result text is removed for other members.','Use o UUID da tabela. roll_table contém entradas e totalWeight; texto exclusivo do mestre é removido para os demais membros.','Authorized entries with weight, active, drawn and sortOrder.','Entradas autorizadas com weight, active, drawn e sortOrder.','Give a player read access and compare a secret table. The player must receive empty result text and cannot roll it.','Dê leitura ao jogador e compare uma tabela secreta. Ele deve receber result vazio e não pode rolá-la.'),
  recipe('set-weight',[rid,text('entryId','Entry ID','fog'),number('weight','Weight, integer 1 to 1000000',2)],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('GM required to preserve complete results.');if(!Number.isInteger(v.weight)||v.weight<1||v.weight>1000000)throw new Error('Invalid weight.');const row=await api.journals.get(v.id,{}, {signal});if(row.type!=='roll_table')throw new Error('Choose a roll_table.');const data=structuredClone(row.roll_table);if(!data.entries.some(entry=>entry.id===v.entryId))throw new Error('Entry not found.');data.entries=data.entries.map(entry=>entry.id===v.entryId?{...entry,weight:v.weight}:entry);delete data.totalWeight;await api.journals.update({journal_id:row.id,version:row.version,title:row.title,visibility:row.visibility,data},{signal,requestId:crypto.randomUUID()});return api.journals.get(row.id,{}, {signal});}`,
    'Change one weight while preserving every other entry','Alterar um peso preservando as demais entradas','As GM, use the exact entry ID. Copy the complete projected table and alter one weight; totalWeight is derived and omitted from the submitted data.','Como mestre, use o ID exato da entrada. Copie a tabela completa e altere um peso; totalWeight é calculado e não entra nos dados enviados.','The chosen weight changes and a fresh totalWeight is computed.','O peso escolhido muda e totalWeight é recalculado.',readBackEN,readBackPT),
  recipe('roll',[rid,text('sceneId','Authorized scene UUID, optional','',false)],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('GM required.');return api.journals.roll({journal_id:v.id,...(v.sceneId.trim()?{mapId:v.sceneId.trim()}:{})},{signal,requestId:crypto.randomUUID()});}`,
    'Draw and publish one table result','Sortear e publicar um resultado da tabela','Run as GM. The native command uses a secure weighted draw, persists drawn when needed and publishes a chat result. Its payload uses mapId for an explicit scene.','Execute como mestre. O comando nativo sorteia com pesos, persiste drawn quando necessário e publica no chat. O payload usa mapId para cena explícita.','The chosen entry and message_id; native chat shows its authorized result.','A entrada escolhida e message_id; o chat nativo mostra o resultado autorizado.','Without replacement, roll twice and verify distinct entries, then a third roll must fail until reset. Do not rerun after a lost response using a new UUID if the same draw is being retried.','Sem reposição, role duas vezes e confira entradas distintas; a terceira deve falhar até reset. Não repita o mesmo sorteio com UUID novo após perder a resposta.'),
  recipe('reset',[rid],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('GM required.');await api.journals.reset({journal_id:v.id},{signal,requestId:crypto.randomUUID()});return api.journals.get(v.id,{}, {signal});}`,
    'Reset drawn flags without changing results','Restaurar marcadores sem alterar resultados','Use the exhausted table UUID. Reset changes drawn to false for every entry; it does not clear native chat or replace table text.','Use o UUID da tabela esgotada. Reset define drawn falso em cada entrada; não limpa o chat nem substitui o texto da tabela.','The active entries are eligible again and totalWeight is restored.','As entradas ativas participam novamente e totalWeight é restaurado.',readBackEN,readBackPT)
];

const journalRecipes=[
  recipe('directory',[],String.raw`async ({api,signal})=>api.journals.state({}, {signal})`,
    'Read documents, folders and campaign member IDs','Ler documentos, pastas e IDs de membros','Run first as GM to obtain journals[].id, folders[].id and members[].id. The last field is a user UUID for setAccess and presentation, not an actor UUID. Player projections omit the GM member directory and private content.','Execute primeiro como mestre para obter journals[].id, folders[].id e members[].id. O último é UUID de usuário para setAccess e apresentação, não UUID de ator. A projeção do jogador omite a lista de membros do mestre e conteúdo privado.','The authorized directory with native types, permissions and feature flags.','O diretório autorizado com tipos nativos, permissões e flags de recursos.',readBackEN,readBackPT),
  recipe('create-diary',[text('title','Original diary title','Harbor log'),text('body','Original body text','The harbor beacon needs repair.')],String.raw`async ({api,signal},v)=>{const created=await api.journals.create({title:v.title,journal_type:'diary'},{signal,requestId:crypto.randomUUID()});try{const doc=text=>({format:'gw-journal-doc-v1',version:1,doc:{type:'doc',content:[{type:'paragraph',content:[{type:'text',text}]}]}});await api.journals.update({journal_id:created.journal_id,version:created.version,title:v.title,data:{content:doc(v.body),cover:{},sections:[],gm:{}}},{signal,requestId:crypto.randomUUID()});return api.journals.get(created.journal_id,{}, {signal});}catch(error){throw new Error('Diary '+created.journal_id+' exists; setup failed: '+(error.code||error.message)+'. Inspect it before creating another.');}}`,
    'Create a real block-document diary','Criar um diário com documento estruturado','Create a diary, then fill content using the supported gw-journal-doc-v1 envelope. Plain HTML or a Markdown string is not that rich-document format. Copy the returned ID.','Crie um diário e preencha content com o envelope gw-journal-doc-v1. HTML puro ou uma string Markdown não são esse formato de documento rico. Copie o ID retornado.','A private diary whose native editor displays the original paragraph.','Um diário privado cujo editor nativo mostra o parágrafo original.',readBackEN,readBackPT),
  recipe('rename-diary',[rid,text('title','New diary title','Harbor log, reviewed')],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('Use GM to preserve the full diary projection.');const row=await api.journals.get(v.id,{}, {signal});if(row.type!=='diary')throw new Error('Choose a diary.');const data={content:row.content_doc,cover:row.cover_image,sections:row.sections,gm:row.diary.gm};await api.journals.update({journal_id:row.id,version:row.version,title:v.title,visibility:row.visibility,data},{signal,requestId:crypto.randomUUID()});return api.journals.get(row.id,{}, {signal});}`,
    'Rename a diary without erasing its pages or GM notes','Renomear diário sem apagar páginas ou notas do mestre','As GM, reconstruct the write shape from the read projection: content_doc becomes content, cover_image becomes cover, and diary.gm becomes gm. Preserve sections and the exact read version. This example deliberately targets diary, not quest/table shapes.','Como mestre, reconstrua o formato de gravação: content_doc vira content, cover_image vira cover e diary.gm vira gm. Preserve sections e a versão lida. A receita atende diary, não formatos de missão ou tabela.','Only the title changes; all authorized page and GM data remains.','Somente o título muda; páginas e dados do mestre permanecem.',readBackEN,readBackPT),
  recipe('move-document',[rid,text('folderId','Target folder UUID, blank for root','',false)],String.raw`async ({api,signal},v)=>{await api.journals.move({journal_id:v.id,target_folder_id:v.folderId.trim()||null},{signal,requestId:crypto.randomUUID()});return api.journals.get(v.id,{}, {signal});}`,
    'Move a document into a folder or the root','Mover documento para pasta ou raiz','As GM, use a folder UUID from the directory. Blank target selects the root. This changes organization rather than visibility or content.','Como mestre, use UUID de pasta do diretório. Destino vazio escolhe a raiz. A ação altera organização, não visibilidade ou conteúdo.','The document folder_id becomes the target UUID or null.','folder_id passa a ser o UUID de destino ou null.',readBackEN,readBackPT),
  recipe('access',[rid,text('userId','Campaign user UUID'),text('level','none/limited/read/owner','read')],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('GM required.');if(!['none','limited','read','owner'].includes(v.level))throw new Error('Invalid access level.');await api.journals.setAccess({journal_id:v.id,target_user_id:v.userId,access_level:v.level},{signal,requestId:crypto.randomUUID()});return api.journals.get(v.id,{}, {signal});}`,
    'Grant or revoke one member’s journal access','Conceder ou revogar acesso de um membro','Use members[].id from the GM directory. none denies access, limited allows listing, read opens authorized content, and owner permits editing under server rules. This persists a grant, unlike a temporary presentation.','Use members[].id do diretório do mestre. none nega acesso, limited permite listagem, read abre conteúdo autorizado e owner permite edição conforme o servidor. A concessão persiste, diferente da apresentação temporária.','A native per-user access grant for that journal.','Uma concessão nativa por usuário para o diário.','Check the targeted player’s list and editor. GM-only blocks must remain hidden even after read access.','Confira lista e editor do jogador alvo. Blocos exclusivos do mestre devem continuar ocultos mesmo com leitura.'),
  recipe('present',[rid,text('userId','Target user UUID, blank for everyone','',false),text('pageId','Public diary page ID, optional','',false)],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('GM required.');const payload={journal_id:v.id,ownership:'unchanged',...(v.userId.trim()?{targets:[v.userId.trim()]}:{}),...(v.pageId.trim()?{page_id:v.pageId.trim()}:{})};return api.journals.present(payload,{signal,requestId:crypto.randomUUID()});}`,
    'Present a player-filtered document or public page','Apresentar documento ou página pública filtrados','Leave user UUID blank to present to everyone, or target one campaign user when targeted handouts are enabled. Optional page ID must refer to a public diary page. ownership unchanged avoids a permanent access change.','Deixe usuário vazio para todos ou escolha um membro quando apresentações direcionadas estiverem habilitadas. O ID opcional deve ser de página pública do diário. ownership unchanged evita alterar o acesso permanente.','A native presentation is delivered to recipients with short-lived read access and player-filtered content.','Uma apresentação nativa é entregue aos destinatários com leitura temporária e conteúdo filtrado para jogador.','Confirm receipt in the targeted account and no delivery to another. Try a GM-only page and expect rejection.','Confirme recebimento na conta alvo e ausência na outra. Tente página exclusiva do mestre e confira a rejeição.'),
  recipe('folder-create',[text('name','Folder name','Harbor notes'),text('parentId','Parent folder UUID, optional','',false)],String.raw`async ({api,signal},v)=>{const result=await api.journals.createFolder({name:v.name,color:'#c09a5a',parent_id:v.parentId.trim()||null},{signal,requestId:crypto.randomUUID()});return {result,directory:await api.journals.state({}, {signal})};}`,
    'Create a folder with a validated color','Criar pasta com cor validada','Enter a name and optionally an existing parent UUID. The native color is a six-digit hexadecimal string. Copy result.folder_id.','Informe nome e, opcionalmente, UUID de pasta pai. A cor nativa é uma string hexadecimal de seis dígitos. Copie result.folder_id.','One new folder, attached to the selected parent.','Uma pasta nova vinculada à pasta pai escolhida.',readBackEN,readBackPT),
  recipe('folder-update',[text('folderId','Folder UUID'),text('name','New folder name','Harbor archive'),text('color','Six-digit color','#5f8fba')],String.raw`async ({api,signal},v)=>{await api.journals.updateFolder({folder_id:v.folderId,name:v.name,color:v.color},{signal,requestId:crypto.randomUUID()});return api.journals.state({}, {signal});}`,
    'Rename and recolor a folder','Renomear e recolorir pasta','Use the folder ID created above. This API requires both name and color, so send them explicitly.','Use o ID da pasta criada. A API exige nome e cor; envie ambos explicitamente.','The same folder ID with its new name and color.','O mesmo ID de pasta com novo nome e cor.',readBackEN,readBackPT),
  recipe('folder-move',[text('folderId','Folder UUID'),text('parentId','New parent UUID, blank for root','',false)],String.raw`async ({api,signal},v)=>{await api.journals.moveFolder({folder_id:v.folderId,target_parent_id:v.parentId.trim()||null},{signal,requestId:crypto.randomUUID()});return api.journals.state({}, {signal});}`,
    'Move a folder without creating cycles','Mover pasta sem criar ciclos','Choose an existing folder and new parent. A blank parent moves to root. The server rejects moving a folder into itself or a descendant.','Escolha pasta existente e novo pai. Pai vazio move para a raiz. O servidor rejeita mover uma pasta para dentro de si ou de uma descendente.','The folder has a new parent_id while its children stay attached.','A pasta tem novo parent_id e mantém seus filhos.','Create a child and attempt to move its parent into it; the operation must fail without changing the tree.','Crie uma filha e tente mover a mãe para dentro dela; a ação deve falhar sem alterar a árvore.'),
  recipe('folder-delete',[text('folderId','Folder UUID'),text('confirmation','Type the exact folder name')],String.raw`async ({api,signal},v)=>{const state=await api.journals.state({}, {signal});const folder=state.folders.find(folder=>folder.id===v.folderId);if(!folder)throw new Error('Folder not found.');if(v.confirmation!==folder.name)throw new Error('Type the exact folder name.');await api.journals.deleteFolder({folder_id:folder.id},{signal,requestId:crypto.randomUUID()});return api.journals.state({}, {signal});}`,
    'Delete a folder while retaining its contents','Apagar pasta preservando o conteúdo','Use only the synthetic folder and type its exact name. Native deletion reparents its child folders and documents to its former parent. It does not recursively delete journals.','Use apenas a pasta sintética e digite seu nome exato. A exclusão nativa move pastas e documentos filhos para a antiga pasta pai. Não apaga diários recursivamente.','The folder disappears, while its documents remain in the parent or root.','A pasta desaparece; seus documentos permanecem na pasta pai ou raiz.',readBackEN,readBackPT),
  recipe('delete-document',[rid,text('confirmation','Type the exact document title')],String.raw`async ({api,context,signal},v)=>{if(context.role!=='gm')throw new Error('GM required.');const row=await api.journals.get(v.id,{}, {signal});if(v.confirmation!==row.title)throw new Error('Type the exact document title.');await api.journals.delete({journal_id:row.id},{signal,requestId:crypto.randomUUID()});return api.journals.list({}, {signal});}`,
    'Delete one disposable document and refresh the list','Apagar um documento descartável e atualizar a lista','As GM, type the exact title of the tutorial document. This deletes that journal and related native references; it is different from removing a board link.','Como mestre, digite o título exato do documento de teste. A ação apaga esse diário e referências nativas relacionadas; difere de remover vínculo de quadro.','The returned list omits the deleted UUID.','A lista retornada omite o UUID apagado.',readBackEN,readBackPT)
];

const definitions=[
  {id:'chat-dice',slug:'tutorial-chat-dice',label:'Chat, dice and lobby',recipes:chatRecipes,
    en:{title:'How to build chat, dice and ready-check tools',summary:'Create a working module that sends messages, publishes rolls, moderates chat, searches documents and updates readiness.',intro:'Build a native-modal workbench with twelve independent actions. Begin with Read history, send a public message, test whisper/GM/emote delivery, roll public and secret dice, then inspect and update the lobby. Moderation is intentionally explicit and restricted to a disposable campaign.',prerequisites:'Use a disposable campaign with two members and one original actor. Enable native ready checks and command search through the installation settings if you want those recipes; their APIs report permission_denied when the feature is disabled. Copy a player display name from the table and document UUIDs from native lists.',validation:'Every action uses the supplied scoped API and a signal. Mutation submissions use a fresh UUID, except lobby/moderation whose native service signatures do not use receipts. To retry the same chat or dice submission in your own integration, retain its UUID and identical payload; clicking Run again is a new logical action. Use two accounts for private audiences and revoked document access. On conflict, read and review state before a new command. The server filters membership, scenes, messages and resource access; disabled buttons are not authorization.',prompt:'Extend this complete chat-dice project on Gravewright 0.3.0 with [one feature]. Read modules/frontend.py, chat/services.py, dice/services.py and table/services.py. Keep native chat command parsing, real lobby snake_case payloads, audience filtering, request UUIDs, permissions and cancellation. Show all files and validate with two users, private messages, stale access and disabled installation features.'},
    pt:{title:'Como criar ferramentas de chat, dados e prontidão',summary:'Crie um módulo funcional para mensagens, rolagens, moderação, busca de documentos e atualização da prontidão.',intro:'Monte um painel em modal nativo com doze ações independentes. Comece lendo o histórico, envie mensagem pública, teste sussurro/GM/ação e role dados públicos e secretos. Depois, leia e atualize o lobby. A moderação é explícita e deve usar campanha descartável.',prerequisites:'Use campanha descartável com dois membros e um ator original. Ative prontidão e busca nativas nas configurações da instalação para essas receitas; as APIs informam permission_denied quando o recurso está desabilitado. Copie nome de jogador da mesa e UUIDs de documentos das listas nativas.',validation:'Cada ação usa API da montagem e signal. Submissões de alteração recebem UUID novo, exceto lobby/moderação cujos serviços nativos não usam recibos. Para tentar a mesma submissão de chat ou dados em sua integração, preserve UUID e payload idênticos; clicar Run novamente é outra ação lógica. Use duas contas para audiências privadas e acesso revogado. Em conflito, leia e revise o estado antes de novo comando. O servidor filtra membros, cenas, mensagens e documentos; desabilitar botões não autoriza operações.',prompt:'Estenda o projeto completo chat-dice no Gravewright 0.3.0 com [um recurso]. Leia modules/frontend.py, chat/services.py, dice/services.py e table/services.py. Preserve parser nativo de comandos, payloads snake_case reais do lobby, audiência, UUIDs, permissões e cancelamento. Mostre todos os arquivos e valide com duas contas, mensagens privadas, acesso revogado e recursos da instalação desabilitados.'},
    sourcePaths:['gravewright/chat/services.py','gravewright/dice/services.py','gravewright/table/services.py','gravewright/modules/frontend.py','gravewright/modules/static/gravewright_modules/domain-api.js']},
  {id:'quests',slug:'tutorial-quests',label:'Quest and board tools',recipes:questRecipes,
    en:{title:'How to create quest automation and quest-board actions',summary:'Create and read a real quest, advance objectives, assign actors and manage every board relationship.',intro:'Build a module for an original harbor quest and job board. Run Create quest, copy its ID, read objective IDs, mark completion and assign a character. Create a board, link the quest, create another through the board, pin and reorder both, then unlink without deleting content.',prerequisites:'Use a disposable campaign as GM. Obtain a readable actor UUID from Actors. For sharing, use the access and presentation recipes in [journal management](docs:tutorial-journal-management); board visibility and player-visible quest statuses both matter.',validation:'Creation plus setup uses separate commands, so a setup failure names the created UUID instead of pretending nothing happened. Repair that object before clicking Create again. Status/objective/assignment edits send the exact read version and never retry conflicts automatically. Board ordering requires every linked quest ID exactly once, including drafts visible to GM. The server enforces ownership and hides private quest fields. Verify as a player after changing draft/available status and explicit grants.',prompt:'Extend the quests tutorial on Gravewright 0.3.0 with [workflow]. Inspect journals/services.py, types.py, data.py and frontend.json. Preserve native quest status values, objective IDs/booleans, assignee limits and board relationship payloads. Never delete a quest to unlink it. Deliver complete recipes, expose partial creation failures and test GM/player projections, hidden objectives, exact versions and board ordering conflicts.'},
    pt:{title:'Como criar automações de missões e ações de quadro',summary:'Crie e leia uma missão real, avance objetivos, atribua atores e gerencie todos os vínculos do quadro.',intro:'Crie um módulo para missão original do porto e quadro de trabalhos. Execute criar missão, copie o ID, leia IDs dos objetivos, conclua um deles e atribua personagem. Crie um quadro, vincule a missão, crie outra pelo quadro, fixe e ordene as duas e depois desvincule sem apagar conteúdo.',prerequisites:'Use campanha descartável como mestre. Obtenha UUID legível de ator em Atores. Para compartilhar, use concessão e apresentação do [gerenciador de diários](docs:tutorial-journal-management); visibilidade do quadro e estados visíveis das missões são relevantes.',validation:'Criar e configurar usa comandos separados; uma falha de configuração informa o UUID criado em vez de ocultar o efeito parcial. Repare o documento antes de clicar criar novamente. Estado, objetivo e atribuição enviam a versão exata lida e não repetem conflitos automaticamente. Ordenar o quadro exige cada missão vinculada uma vez, incluindo rascunhos visíveis ao mestre. O servidor verifica propriedade e oculta campos privados. Verifique como jogador após alternar draft/available e concessões explícitas.',prompt:'Estenda o tutorial quests no Gravewright 0.3.0 com [fluxo]. Leia journals/services.py, types.py, data.py e frontend.json. Preserve estados nativos, IDs/booleanos de objetivos, limites de atribuídos e payloads dos vínculos do quadro. Não apague missão para desvincular cartão. Entregue receitas completas, informe criações parciais e teste projeções mestre/jogador, objetivos ocultos, versões exatas e conflitos de ordenação.'},
    sourcePaths:['gravewright/journals/services.py','gravewright/journals/types.py','gravewright/journals/data.py','gravewright/modules/contracts/frontend.json']},
  {id:'roll-tables',slug:'tutorial-roll-tables',label:'Roll table tools',recipes:rollRecipes,
    en:{title:'How to create, draw and reset weighted roll tables',summary:'Build an original journal roll table, edit a weight without losing data and publish native draws with or without replacement.',intro:'Create a two-entry harbor-weather table, inspect its real schema, change a weight, draw until it is exhausted and reset it. This uses journal_type roll_table rather than a compendium pack or a system-specific random table.',prerequisites:'Use a disposable campaign as GM and a second player account for audience checks. Keep all entry results original. Use an authorized scene UUID only if the draw should target that scene; otherwise the native broadcast context is used.',validation:'Only GMs can roll or reset. A read-access player may inspect authorized metadata but receives no hidden result text for resultVisibility gm. With replacement false, two active entries allow two draws, then no entry remains. Reset restores eligibility without rerolling or clearing chat. Table edits preserve all entries and exact version; do not copy a filtered player projection back as a complete GM table. Handle a setup failure using its returned created UUID.',prompt:'Extend roll-tables on Gravewright 0.3.0 with [behavior]. Read normalize_roll_table_data, journals.types.apply and the public browser mapping. Keep weighted native draws, active/drawn flags, withReplacement, resultVisibility, GM-only roll/reset, exact update versions and retry UUIDs. Supply complete entries and test exhaustion, reset, private results and a missing scene.'},
    pt:{title:'Como criar, sortear e restaurar tabelas de rolagem',summary:'Crie uma tabela de diário original, altere um peso preservando dados e publique sorteios nativos com ou sem reposição.',intro:'Crie tabela de clima do porto com duas entradas, leia seu formato real, altere um peso, sorteie até esgotar e restaure. O tipo é journal_type roll_table, diferente de pack de compêndio ou tabela específica de sistema.',prerequisites:'Use campanha descartável como mestre e uma segunda conta de jogador para conferir audiência. Use resultados originais. Informe cena autorizada apenas se o sorteio deve ter aquela cena como alvo; caso contrário, usa o contexto nativo de transmissão.',validation:'Somente mestres podem sortear ou restaurar. Um jogador com leitura vê metadados autorizados, mas não texto de resultado quando resultVisibility é gm. Com reposição falsa, duas entradas ativas permitem dois sorteios até esgotar. Reset restaura participação sem sortear ou limpar chat. Edições preservam todas as entradas e a versão exata; não envie projeção filtrada de jogador como tabela completa do mestre. Repare falha de configuração pelo UUID criado informado.',prompt:'Estenda roll-tables no Gravewright 0.3.0 com [comportamento]. Leia normalize_roll_table_data, journals.types.apply e o mapeamento público. Preserve sorteio nativo com pesos, active/drawn, withReplacement, resultVisibility, roll/reset exclusivos do mestre, versão exata e UUID de tentativa. Entregue entradas completas e teste esgotamento, restauração, resultados privados e cena ausente.'},
    sourcePaths:['gravewright/journals/data.py','gravewright/journals/types.py','gravewright/journals/services.py','gravewright/modules/frontend.py']},
  {id:'journal-management',slug:'tutorial-journal-management',label:'Journal management tools',recipes:journalRecipes,
    en:{title:'How to create, organize and share journal documents',summary:'Build native rich diaries, preserve pages when editing, organize folder trees and control access and presentations.',intro:'Begin with the native directory read. Create an original diary, rename it without replacing its pages, move it through a folder tree, grant one player read access and present a public page. The final recipes delete only explicitly confirmed tutorial resources.',prerequisites:'Use a disposable campaign as GM for complete projections and destructive actions. Copy user UUIDs from members, folder UUIDs from folders and document UUIDs from journals. A diary page ID comes from sections[].id, not a scene or actor ID. Targeted presentation requires the corresponding native installation feature.',validation:'Folder operations are not recursive document deletion: deleting a folder reparents its documents and children. Deleting a document is separate and requires exact-title confirmation here. update requires exact version and the correct per-type data envelope; the diary recipe reconstructs its GM projection while keeping pages, cover and private notes. Access persists; a presentation with ownership unchanged gives temporary player-filtered read access. Check targeted/non-targeted users, private pages, tree cycles and stale edits.',prompt:'Extend journal-management on Gravewright 0.3.0 with [one workflow]. Read journals/services.py, documents.py, data.py and presentations.py. Preserve gw-journal-doc-v1, diary read/write shape conversion, exact versions, folder containment, targeted handout access and private content filtering. Deliver complete recipes and tests for GM/player, duplicate moves, rejected cycles, page privacy and separate document versus folder deletion.'},
    pt:{title:'Como criar, organizar e compartilhar documentos de diário',summary:'Crie diários ricos nativos, preserve páginas ao editar, organize pastas e controle acesso e apresentações.',intro:'Comece lendo o diretório nativo. Crie diário original, renomeie sem substituir páginas, mova na árvore de pastas, dê leitura a um jogador e apresente uma página pública. As receitas finais removem somente recursos de tutorial confirmados explicitamente.',prerequisites:'Use campanha descartável como mestre para projeções completas e ações destrutivas. Copie UUIDs de usuários de members, pastas de folders e documentos de journals. ID de página vem de sections[].id, não de cena ou ator. Apresentação direcionada exige o recurso nativo da instalação.',validation:'Operações de pasta não apagam documentos recursivamente: excluir pasta move seus documentos e filhos para a pasta pai. Excluir documento é separado e exige título exato neste exemplo. update exige versão exata e envelope do tipo correto; a receita de diário reconstrói a projeção de mestre preservando páginas, capa e notas privadas. A concessão de acesso persiste; apresentar com ownership unchanged dá leitura temporária filtrada para jogador. Confira destinatários, páginas privadas, ciclos na árvore e edições desatualizadas.',prompt:'Estenda journal-management no Gravewright 0.3.0 com [um fluxo]. Leia journals/services.py, documents.py, data.py e presentations.py. Preserve gw-journal-doc-v1, conversão dos formatos de leitura/gravação, versões exatas, contenção de pastas, acesso direcionado e filtragem privada. Entregue receitas completas e testes mestre/jogador, movimentos repetidos, ciclos rejeitados, privacidade de páginas e exclusão separada de documentos/pastas.'},
    sourcePaths:['gravewright/journals/services.py','gravewright/journals/documents.py','gravewright/journals/data.py','gravewright/journals/presentations.py','gravewright/modules/contracts/frontend.json']}
];
